#include "Rover.h"

void bump(int size) {
  turnLeft();
  forward(1);
  turnRight();
  forward(size);
  turnRight();
  forward(1);
  turnLeft();
}

void setup() {
  bump(2);
  forward(2);
  bump(4);
  forward(2);
  bump(3);
}

void loop() {
}
